import numpy as np
from scipy.optimize import minimize_scalar
def basis(b):
    e=np.exp(-b*P)
    cols=[];names=[]
    for k in range(3):
        for j in range(3):
            cols.append(P**k*t**j); names.append(f'P{k}t{j}')
    for j in range(3):
        cols.append(e*t**j); names.append(f'e t{j}')
    for j in range(2):
        cols.append(e*P*t**j); names.append(f'eP t{j}')
    return np.column_stack(cols),names
def f(b):
    X,_=basis(b)
    cc=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((X@cc-dP_dt)**2)/np.var(dP_dt)
